void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
bool until(const std::function<bool()>& ready){const auto end=GetTickCount64()+8000;do{MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}if(ready())return true;Sleep(20);}while(GetTickCount64()<end);return false;}
std::vector<HWND> windows(DWORD root,bool child=false){struct Scan{DWORD pid;std::vector<HWND> found;} scan{root,{}};auto collect=[](HWND h,LPARAM data)->BOOL{auto& s=*reinterpret_cast<Scan*>(data);DWORD pid=0;GetWindowThreadProcessId(h,&pid);if(pid==s.pid)s.found.push_back(h);return TRUE;};if(child)EnumChildWindows(GetDesktopWindow(),collect,reinterpret_cast<LPARAM>(&scan));else EnumWindows(collect,reinterpret_cast<LPARAM>(&scan));return scan.found;}
HWND owned(DWORD root,const wchar_t* title){for(auto h:windows(root))if(win::windowText(h)==title)return h;return nullptr;}
win::ComPtr<IAccessible> access(HWND h){win::ComPtr<IAccessible> p;check(SUCCEEDED(AccessibleObjectFromWindow(h,static_cast<DWORD>(OBJID_CLIENT),IID_PPV_ARGS(&p))),"Owned accessibility missing");return p;}
void named(HWND h,const std::wstring& name,bool activate=true){auto p=access(h);long count=0;p->get_accChildCount(&count);for(long n=1;n<=count;++n){VARIANT id{};id.vt=VT_I4;id.lVal=n;BSTR text=nullptr;p->get_accName(id,&text);bool found=text&&std::wstring_view(text)==name;SysFreeString(text);if(found){check(SUCCEEDED(p->accSelect(SELFLAG_TAKEFOCUS,id)),"Owned control cannot take focus");p=access(h);if(activate)check(p->accDoDefaultAction(id)==S_OK,"Owned control did not invoke");return;}}throw std::runtime_error("Named owned control missing");}
void switchAt(DWORD root,int index){auto controller=owned(root,L"Aether UI Controller");if(auto old=owned(root,L"Aether Activities");old&&IsWindowVisible(old))SendMessageW(old,WM_CLOSE,0,0);AllowSetForegroundWindow(root);PostMessageW(controller,WM_APP+42,0,0);HWND overview=nullptr;check(until([&]{overview=owned(root,L"Aether Activities");return overview&&IsWindowVisible(overview)&&!GetPropW(overview,L"Aether.Overview.Animating");}),"Actual strip did not open");auto p=access(overview);VARIANT id{};id.vt=VT_I4;id.lVal=4000+index;check(p->accDoDefaultAction(id)==S_OK,"Actual strip did not switch");check(until([&]{return !IsWindowVisible(overview);}),"Actual strip did not close");}
std::vector<HWND> scenes(DWORD root){std::vector<HWND> out;for(auto h:windows(root,true))if(win::windowText(h)==L"Aether animated wallpaper")out.push_back(h);std::sort(out.begin(),out.end());return out;}
void hiddenTaskbars(){const auto started=GetTickCount64();bool observedVisible=false;check(until([&]{DWORD explorer=0;GetWindowThreadProcessId(GetShellWindow(),&explorer);std::vector<HWND> bars;EnumWindows([](HWND h,LPARAM p)->BOOL{wchar_t cls[128]{};GetClassNameW(h,cls,128);if(!wcscmp(cls,L"Shell_TrayWnd")||!wcscmp(cls,L"Shell_SecondaryTrayWnd"))reinterpret_cast<std::vector<HWND>*>(p)->push_back(h);return TRUE;},reinterpret_cast<LPARAM>(&bars));for(const auto* name:{L"Shell_TrayWnd",L"Shell_SecondaryTrayWnd"}){HWND after=nullptr;for(int i=0;i<33;++i){auto h=FindWindowExW(nullptr,after,name,nullptr);if(!h)break;after=h;if(std::find(bars.begin(),bars.end(),h)==bars.end())bars.push_back(h);}}int count=0;bool hidden=true;for(auto h:bars){DWORD pid=0;GetWindowThreadProcessId(h,&pid);if(pid==explorer){++count;hidden&=!IsWindowVisible(h);}}observedVisible|=!hidden;return count==static_cast<int>(win::monitors().size())&&hidden;}),"Native taskbar guard did not restore hiding");if(observedVisible)std::cout<<"OBSERVED taskbar became visible during shell transition; guard rehid it within "<<(GetTickCount64()-started)<<" ms; uninterrupted hiding not claimed\n";}

